import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week7/generated/day2-status-families.spec.ts", `// Week 7, Day 2 — the four status-code families, each fetched for real.
//
// Written by a cell in week7/day2_2.ipynb. Run it yourself:
//   npx playwright test week7/generated/day2-status-families.spec.ts
import { test, expect } from "@playwright/test";

const DEMOQA = "https://demoqa.com";
const INTERNET = "https://the-internet.herokuapp.com";

test.describe("Status code families", () => {
  test("Step 1 — 2xx: it worked", async ({ request }) => {
    const response = await request.get(\`\${DEMOQA}/BookStore/v1/Books\`);

    expect(response.status()).toBe(200);
    expect(response.ok()).toBe(true);   // ok() is true for any 2xx
  });

  test("Step 2 — 3xx: go and ask over there instead", async ({ request }) => {
    // maxRedirects: 0 stops Playwright following it, so we can SEE the 302.
    // Without this you get the 200 from the destination and never know a
    // redirect happened — which is why the session had to open DevTools.
    const response = await request.get(\`\${INTERNET}/redirect\`, { maxRedirects: 0 });

    expect(response.status()).toBe(302);
    // A 3xx is only useful with its Location header: that is the "over there".
    expect(response.headers()["location"]).toContain("/status_codes");
  });

  test("Step 3 — 4xx: you asked for something wrong", async ({ request }) => {
    const response = await request.get(\`\${DEMOQA}/BookStore/v1/Book?ISBN=0000000000\`);

    // The session expects 404 here. This API answers 400 with a message code.
    // Both are 4xx — "your request was the problem" — and the exact number is
    // the developer's choice, not a rule. Read the response; do not assume.
    expect(response.status()).toBe(400);
    const body = await response.json();
    expect(body.code).toBe("1205");
    expect(body.message).toContain("not available in Books Collection");
  });

  test("Step 4 — 404 is a 4xx too, just a more famous one", async ({ request }) => {
    const response = await request.get(\`\${INTERNET}/status_codes/404\`);
    expect(response.status()).toBe(404);
  });

  test("Step 5 — 5xx: the server broke, not you", async ({ request }) => {
    const response = await request.get(\`\${INTERNET}/status_codes/500\`);

    expect(response.status()).toBe(500);
    expect(response.ok()).toBe(false);
    // Nothing to fix in your test. This one is a bug report for the API team.
  });
});

test.describe("Why a status code alone is not a verification", () => {
  test("Step 6 — a 200 that means failure", async ({ request }) => {
    const response = await request.post(\`\${DEMOQA}/Account/v1/GenerateToken\`, {
      data: { userName: "user_that_does_not_exist_w7", password: "WrongPass@1" },
    });

    // 200. Success, surely?
    expect(response.status()).toBe(200);

    const body = await response.json();
    // No. The body says it failed and hands back no token.
    expect(body.status).toBe("Failed");
    expect(body.token).toBeNull();
    expect(body.result).toContain("authorization failed");
  });
});
`);

// Expected: 6 passed. One test per family, plus the 200 that means failure.
await runSpec("week7/generated/day2-status-families.spec.ts");

// The same trap, in four lines you can run.
const tokenResponse = await fetch("https://demoqa.com/Account/v1/GenerateToken", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ userName: "nobody_at_all_w7", password: "WrongPass@1" }),
});

console.log("status  :", tokenResponse.status, "<- looks like success");
const tokenBody = await tokenResponse.json();
console.log("status field:", tokenBody.status);
console.log("token       :", tokenBody.token, "<- there is no token");

// The docs describe one book lookup. Check three things they do not spell out.
const base = "https://demoqa.com/BookStore/v1";

const good = await fetch(`${base}/Book?ISBN=9781449325862`);
console.log("known ISBN     ->", good.status);

const bad = await fetch(`${base}/Book?ISBN=0000000000`);
console.log("unknown ISBN   ->", bad.status, JSON.stringify(await bad.json()));

const missing = await fetch(`${base}/Book`);
console.log("no ISBN at all ->", missing.status, (await missing.text()).slice(0, 70));

// Authenticate once, then authorise a call with what you got.
const B = "https://demoqa.com";
const J = { "Content-Type": "application/json" };
const who = { userName: `w7d2_${Date.now()}`, password: "Passw0rd@123" };

const made = await fetch(`${B}/Account/v1/User`, { method: "POST", headers: J, body: JSON.stringify(who) });
const madeBody = await made.json();
console.log("create user      ->", made.status, "id:", madeBody.userID?.slice(0, 8) + "...");

const tokenRes = await fetch(`${B}/Account/v1/GenerateToken`, { method: "POST", headers: J, body: JSON.stringify(who) });
const bearer = (await tokenRes.json()).token;
console.log("authenticate     ->", tokenRes.status, "token starts:", bearer.slice(0, 18) + "...");

const noAuth = await fetch(`${B}/Account/v1/User/${madeBody.userID}`);
console.log("read WITHOUT it  ->", noAuth.status, "<- 401, not allowed");

const withAuth = await fetch(`${B}/Account/v1/User/${madeBody.userID}`, {
  headers: { Authorization: `Bearer ${bearer}` },
});
console.log("read WITH it     ->", withAuth.status);

await fetch(`${B}/Account/v1/User/${madeBody.userID}`, {
  method: "DELETE", headers: { Authorization: `Bearer ${bearer}` },
});
console.log("cleaned up (this is a shared public sandbox)");
